CALL (
    WITH s
    MATCH (s)-[:HAS_INVENTORY]->(rootInv:Inventory)
    WHERE rootInv.version = (
        MATCH (s)-[:HAS_INVENTORY]->(i:Inventory)
        RETURN max(i.version)
    )
    // Recursive CTE to find all parts
    WITH rootInv
    CALL (
        WITH rootInv
        // Base case: parts directly in rootInv
        MATCH (rootInv)-[:HAS_PART {is_spare: false}]->(p:Part)
        RETURN p.part_num AS part_num
        UNION
        // Recursive case: parts in nested sets/minifigs
        MATCH (rootInv)-[:CONTAINS_SET]->(nestedSet:Set)-[:HAS_INVENTORY]->(nestedInv:Inventory)
        WHERE nestedInv.version = (
            MATCH (nestedSet)-[:HAS_INVENTORY]->(ni:Inventory)
            RETURN max(ni.version)
        )
        WITH nestedInv
        CALL (
            WITH nestedInv
            MATCH (nestedInv)-[:HAS_PART {is_spare: false}]->(p:Part)
            RETURN p.part_num AS part_num
            UNION
            MATCH (nestedInv)-[:CONTAINS_SET]->(nestedSet2:Set)-[:HAS_INVENTORY]->(nestedInv2:Inventory)
            WHERE nestedInv2.version = (
                MATCH (nestedSet2)-[:HAS_INVENTORY]->(ni2:Inventory)
                RETURN max(ni2.version)
            )
            WITH nestedInv2
            CALL (
                WITH nestedInv2
                MATCH (nestedInv2)-[:HAS_PART {is_spare: false}]->(p:Part)
                RETURN p.part_num AS part_num
                UNION
                MATCH (nestedInv2)-[:CONTAINS_MINIFIG]->(minifig2:Minifig)-[:HAS_INVENTORY]->(minifigInv2:Inventory)
                WHERE minifigInv2.version = (
                    MATCH (minifig2)-[:HAS_INVENTORY]->(mi2:Inventory)
                    RETURN max(mi2.version)
                )
                WITH minifigInv2
                CALL (
                    WITH minifigInv2
                    MATCH (minifigInv2)-[:HAS_PART {is_spare: false}]->(p:Part)
                    RETURN p.part_num AS part_num
                )
            )
        )
    )
