CALL (
    WITH root_inv AS start_inv
    RETURN start_inv.id AS inv_id, 1.0 AS multiplier
    UNION ALL
    WITH inv_id, multiplier
    MATCH (inv:Inventory {id: inv_id})-[:CONTAINS_SET {qty: q}]->(nested_set:Set)
    MATCH (nested_set)-[:HAS_INVENTORY]->(nested_inv:Inventory)
    WHERE nested_inv.version = (
        MATCH (ns2:Set)-[:HAS_INVENTORY]->(ni2:Inventory)
        WHERE ns2 = nested_set
        RETURN max(ni2.version)
    )
    RETURN nested_inv.id AS inv_id, multiplier * q AS multiplier
    UNION ALL
    WITH inv_id, multiplier
    MATCH (inv:Inventory {id: inv_id})-[:CONTAINS_MINIFIG {qty: q}]->(minifig:Minifig)
    MATCH (minifig)-[:HAS_INVENTORY]->(min_inv:Inventory)
    WHERE min_inv.version = (
        MATCH (m2:Minifig)-[:HAS_INVENTORY]->(mi2:Inventory)
