```cypher
MATCH (s:Set {set_num: '45801-1'})-[:HAS_INVENTORY]->(inv:Inventory)
WHERE inv.version = (
    MATCH (s2:Set {set_num: '45801-1'})-[:HAS_INVENTORY]->(i:Inventory)
    RETURN max(i.version)
)
MATCH path = (inv)-[rels: (CONTAINS_SET|CONTAINS_MINIFIG|HAS_INVENTORY|HAS_PART)*1..10]->(part:Part)
WHERE last(rels).type = 'HAS_PART'
WITH rels(path) AS rel_list
WITH rel_list, list_product([r IN rel_list WHERE r.qty IS NOT NULL | r.qty]) AS path_qty
WITH sum(path_qty) AS total_qty,
     sum(CASE WHEN size(rel_list) = 1 THEN path_qty ELSE 0 END) AS direct_qty
RETURN round((total_qty - direct_qty) * 100.0 / total_qty, 2) AS percentage
