MATCH (s:Set {set_num: '391114-1'})
WITH s
MATCH (s)-[e_cur:CONTAINS]->()
WITH s, max(e_cur.version) AS cur_ver

// Direct parts
MATCH (s)-[e1:CONTAINS]->(p1:Part)
WHERE e1.version = cur_ver AND NOT e1.is_spare
WITH s, cur_ver, sum(e1.qty) AS direct_qty

// Indirect parts from nested sets and minifigs
MATCH (s)-[e1:CONTAINS]->(item)-[e_rest:CONTAINS*1..10 (r, n | WHERE r.is_spare = false)]->(p:Part)
WHERE e1.version = cur_ver
  AND (item:Minifig OR item:Set)
WITH s, direct_qty,
     sum(e1.qty * list_product(properties(rels(e_rest), 'qty'))) AS indirect_qty

WITH direct_qty, indirect_qty
WITH direct_qty + indirect_qty AS total_qty, indirect_qty
RETURN round(100.0 * indirect_qty / total_qty, 2) AS percentage
