  AND NOT EXISTS { MATCH (s)-[c:CONTAINS]->() WHERE c.version > r1.version }
  AND NOT EXISTS { MATCH (a)-[c:CONTAINS]->() WHERE c.version > r2.version }
  AND NOT EXISTS { MATCH (b)-[c:CONTAINS]->() WHERE c.version > r3.version }
  AND NOT EXISTS { MATCH (d)-[c:CONTAINS]->() WHERE c.version > r4.version }
WITH direct, l2, l3, coalesce(sum(r1.qty * r2.qty * r3.qty * r4.qty), 0) AS l4
WITH direct, l2 + l3 + l4 AS nested
RETURN round(100.0 * nested / (direct + nested), 2) AS pct_from_nested
```

